let D, view='overview', filter='', jurisdiction='all', statusFilter='all', page=0, selection=new Set(), recordTab='lines', compareFrom='v2', drawerReturn=null;
let sessionToken='';try{sessionToken=sessionStorage.getItem('workpaper-session')||''}catch{}
let contextEpoch=0, switchingRole=false, requestBusy=false;
const roleLabels={preparer:'Preparer',reviewer:'Reviewer',partner:'Partner',firm_administrator:'Firm administrator',quality_reviewer:'Quality reviewer',client:'Client'};
const roleHomes={preparer:'records',reviewer:'reconciliation',partner:'filing',firm_administrator:'firm',quality_reviewer:'activity',client:'overview'};
const actionPermissions={addLine:'add_line',reviewAdjustment:'review_adjustment',recordCalculation:'calculation',outsideFiling:'outside_filing',relatedReview:'related_review',filingEvent:'filing_event',noticeResponse:'notice_response',noticeReview:'notice_response',rollForward:'roll_forward',nextyearTask:'nextyear_update',nextyearStage:'nextyear_update',nextyearComplete:'nextyear_update',retentionPolicy:'retention_policy',manageTeam:'manage_team',assignForm:'assign_form',formStage:'form_stage',verify:'verify',verifyNext:'verify',noteNext:'note',verifyBatch:'verify',undoBatch:'undo_verify',adjust:'adjust',undoAdjustment:'undo_adjust',resolveNext:'resolve',resolve:'resolve',reopen:'reopen',note:'note',resolveNote:'resolve_note',judgment:'judgment',reviewJudgment:'review_judgment',attach:'evidence',downloadEvidence:'reveal',link:'link',document:'document',area:'area',step:'step',sign:'sign',task:'task',taskUpdate:'task_update',version:'version',importVersion:'import_version',freeze:'freeze',amend:'amend',approve:'approve',standards:'standards',budget:'budget',editAccess:'manage_access',time:'time',seen:'seen',reveal:'reveal',fullExport:'export_full',export:'export'};
function canView(name){return D?.capabilities?.views?.includes(name)===true}
function canInspect(){return canView('records')}
const localActions={adjustmentReview:canInspect,formDisplay:canInspect,reviewTab:()=>canView('review'),reportExport:()=>canAction('export'),clientCopy:()=>D?.user.role==='client',teamWork:()=>!!D?.workflow,ownedForm:canInspect,exportChoice:()=>canAction('export')||canAction('fullExport'),workTab:canInspect,planningTab:()=>canView('changes'),versionLine:()=>canView('changes'),openForm:canInspect,formsHome:canInspect,recordMode:canInspect,returnForm:canInspect,traceBack:()=>true,nextReview:canInspect,close:()=>true,drawerBack:()=>true,mobile:()=>true,refresh:()=>true,notifications:()=>true,evidenceNav:()=>canView('documents'),docPrevious:()=>canView('documents'),docNext:()=>canView('documents'),readiness:()=>['preparer','reviewer','partner'].includes(D?.user.role),adjustments:canInspect,inspectAdjustment:canInspect,scenario:()=>canView('changes'),versionExample:()=>D?.capabilities?.actions.includes('import_version'),planning:()=>canView('changes')};
function canAction(action,id){const permission=actionPermissions[action];if(!permission)return localActions[action]?.()===true;if(!D?.capabilities?.actions.includes(permission))return false;if(permission==='task_update'&&id&&!['preparer','reviewer','partner'].includes(D.user.role))return D.state.tasks.some(t=>t.id===id&&t.assignee===D.user.id);return true}
function roleOptions(){return D.staff.map(u=>`<option value="${u.id}" ${u.id===D.user.id?'selected':''}>${esc(u.name)}  -  ${esc(roleLabels[u.role])}${u.sensitive_data_clearance===false?' · Limited data':''}</option>`).join('')}
function roleSwitcher(){return `<label class="role-control" for="role"><span>Workspace user</span><select id="role" aria-label="Switch role" ${switchingRole||requestBusy?'disabled':''}>${roleOptions()}</select></label>`}
function roleBanner(){return `<details class="role-banner"><summary>${esc(roleLabels[D.user.role])} permissions</summary><p>${esc(D.capabilities?.description||'')}</p></details>`}
function accessKey(data){return JSON.stringify([data.user.id,data.user.role,data.capabilities])}
function resetRoleWorkspace(){salesFilters={company:'',from:'',to:'',sort:'date'};reviewSection='review';workScope='all';compareTo='';activeForm='';recordMode='forms';reviewQueue=[];selection.clear();filter='';page=0;statusFilter='all';jurisdiction='all';recordTab='lines';view=roleHomes[D.user.role]||'overview';closeDrawer();if(typeof window!=='undefined')window.scrollTo(0,0)}
function rememberRole(){if(D.session_token){sessionToken=D.session_token;delete D.session_token}try{sessionStorage.setItem('workpaper-role',D.user.id);sessionStorage.setItem('workpaper-session',sessionToken)}catch{}}
async function switchRole(id){if(switchingRole||requestBusy)return;switchingRole=true;const epoch=++contextEpoch;const control=$('#role');if(control)control.disabled=true;try{const next=await api('session',{id});if(epoch!==contextEpoch)return;D=next;rememberRole();resetRoleWorkspace();render();toast(`Switched to ${D.user.name} · ${roleLabels[D.user.role]}`)}catch(e){if(control)control.value=D.user.id;toast('Could not switch role: '+e.message)}finally{switchingRole=false;const control=$('#role');if(control)control.disabled=false}}
const $=s=>document.querySelector(s), esc=v=>String(v??'').replaceAll('\u2014',' - ').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',check:'m5 12 4 4L19 6',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M6 11h12v10H6z M8 11V7a4 4 0 0 1 8 0v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 m-5-5 5 5-5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',layers:'m12 2 10 5-10 5L2 7z M2 12l10 5 10-5 M2 17l10 5 10-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',chevron:'m9 5 7 7-7 7',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18',chart:'M4 3v18h17 M8 16v-4 M13 16V7 M18 16V4',plus:'M12 5v14 M5 12h14',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',mail:'M3 5h18v14H3z m0 0 9 8 9-8',undo:'M3 4v6h6 M3 10a9 9 0 1 1 2 10',eye:'M2 12s4-8 10-8 10 8 10 8-4 8-10 8-10-8-10-8 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',menu:'M3 6h18 M3 12h18 M3 18h18'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`}
function fmt(n){if(n===null||n===undefined)return ' - ';if(typeof n!=='number')return esc(n);return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n)}
function num(n){return Number(n).toLocaleString('en-US')}
function initials(n){return n.split(' ').map(x=>x[0]).slice(0,2).join('')}
function date(v){return v?new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?v+'T12:00:00Z':v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/Los_Angeles'}):' - '}
function tag(text,color=''){return `<span class="tag ${color}">${esc(text)}</span>`}
function btn(text,action,classes='',extra=''){if(['reviewer','partner'].includes(D?.user.role)&&['verify','verifyNext','verifyBatch','undoBatch'].includes(action))text=text.replace(/Verify/g,'Confirm review').replace(/verification/g,'review confirmation');if(!canAction(action,extra.match(/data-id="([^"]+)"/)?.[1]))return '';return `<button class="btn ${classes}" data-action="${action}" ${extra}>${text}</button>`}
function ref(r){return `<button class="ref-chip" data-ref="${esc(r)}">${icon(r.startsWith('doc:')?'file':'link')} ${esc(r)}</button>`}
function refs(rr){return rr.map(ref).join('')}
function raw(o){return recordPresentation(o)}
function allVersions(){return [...D.packet.return_versions,...(D.state.imported_versions||[])]}
function rv(){const v=allVersions().find(x=>x.version===D.state.version);return {...v,lines:[...v.lines,...(D.state.supplemental_lines||[]).filter(l=>l.version===v.version&&!v.lines.some(x=>x.key===l.key))]}}
function displayValue(n,key=''){const l=lineMap()[key]; if(typeof n!=='number')return fmt(n); if(/miles/i.test(l?.label||''))return num(n)+' mi'; if(/ratio|percentage|rate|divided by/i.test(l?.label||'')&&Math.abs(n)<=1)return (n*100).toFixed(2)+'%'; return fmt(n)}
function lineMap(){return Object.fromEntries(rv().lines.map(l=>[l.key,l]))}
function val(k){return D.state.adjustments[k]?.value??lineMap()[k]?.value}
function openChecks(){return D.checks.filter(c=>!c.resolution)}
function who(id){return D.staff.find(x=>x.id===id)?.name||id}
async function api(path,body){if(body&&['action','reveal','export_full','report'].includes(path))body={...body,actor_id:D?.user.id};const r=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(sessionToken?{'X-Workpaper-Session':sessionToken}:{})},body:body?JSON.stringify(body):undefined});let j=await r.json();if(!r.ok){const error=Error(j.error||'Request failed');error.status=r.status;throw error}return j}
async function load(){const epoch=++contextEpoch,next=await api('state');if(epoch!==contextEpoch)return;if(D&&accessKey(D)!==accessKey(next)){D=next;resetRoleWorkspace()}else D=next;rememberRole();render()}
async function action(a,p={}){if(switchingRole||requestBusy)throw Error('Wait for the current request to finish.');requestBusy=true;const epoch=++contextEpoch;if($('#role'))$('#role').disabled=true;try{const next=await api('action',{revision:D.state.revision,action:a,payload:p});if(epoch===contextEpoch){D=next;render()}return D}finally{requestBusy=false;if($('#role'))$('#role').disabled=false}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function panel(title,body,actionHtml='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${actionHtml}</div>${body}</section>`}
const titles={overview:'Engagement overview',reconciliation:'Reconciliation',documents:'Evidence library',records:'Workpaper records',changes:'Versions & scenarios',review:'Review & collaboration',filing:'Filing & archive',activity:'Activity & view logs',firm:'Firm standards & budget',access:'People & access'};
function render(){if(!canView(view))view=roleHomes[D.user.role]||'overview';if(D.client)return renderClient();if(D.administration)return renderAdministration();if(consolidatedLayout&&view==='reconciliation'){view='records';recordTab='lines';recordMode='issues'}const st=D.state, rvv=rv(), done=Object.keys(st.verifications).length, pending=openChecks().length;
$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand">${brandWordmark()}</div><div class="brand-sub">INTELLIGENCE FOR ALL</div><div class="workspace">${icon('layers')}<div><strong>Tax advisory</strong>Internal workspace</div></div><div class="nav-label">ENGAGEMENT</div><nav class="nav">${unifiedNavs.filter(([id])=>canView(id)).map(([id,ic,t])=>`<button data-nav="${id}" class="${view===id?'active':''}">${icon(ic)}${t}${id==='reconciliation'?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="nav-label">FIRM</div><nav class="nav"><button data-nav="activity" class="${view==='activity'?'active':''}">${icon('clock')}Activity & view logs</button><button data-nav="firm" class="${view==='firm'?'active':''}">${icon('settings')}Standards & budget</button></nav><div class="side-bottom"><div class="privacy">${icon('lock')}<span>Tax workpapers<br>Evidence · Review · Sign-off</span></div><div class="user"><span class="avatar">${initials(D.user.name)}</span><div><strong>${esc(D.user.name)}</strong><small>${esc(roleLabels[D.user.role])}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="nav-toggle" data-action="mobile" aria-label="Toggle navigation">${icon('menu')}</button><span>Engagements</span><span>/</span>Okafor–Lindqvist<span>/</span><strong>2025</strong></div><div class="top-tools">${roleSwitcher()}<label class="search">${icon('search')}<input id="global-search" placeholder="Search this engagement…" aria-label="Search engagement"><span class="key">Ctrl K</span></label>${assignmentBell()}<span class="avatar">${initials(D.user.name)}</span></div></header><div class="content" data-view="${view}">${roleBanner()}<div class="eyebrow">CLIENT WORKPAPER <span class="separator">/</span> TY 2025 <span class="separator">/</span> ${esc(D.packet.packet.client_id)}</div><div class="page-heading"><div><h1>${view==='overview'?'Okafor–Lindqvist household':workspaceTitle(view)}</h1><div class="heading-meta subtitle"><span>${view==='overview'?'A clear line from every number to its evidence.':'Okafor–Lindqvist household'}</span><span class="separator">·</span><span>Federal & California</span>${tag(st.frozen?'Workpaper frozen':'In review',st.frozen?'green':'amber')}<span class="version-pill">${st.version.toUpperCase()} · ${date(rvv.computed_at)}</span></div></div><div class="actions">${btn(icon('check')+' Review readiness','readiness','primary')}</div></div>${['overview','records','review'].includes(view)?engagementHeader():''}${view==='overview'?overview():view==='reconciliation'?reconciliation():view==='documents'?documents():view==='records'?records():view==='changes'?changes():view==='review'?review():view==='filing'?filing():view==='activity'?activity():firm()}<div class="bottom-note"><span>${icon('lock')} Evidence preserved · Changes attributed · Revision ${st.revision}</span><span>${icon('check')} Saved · ${num(D.packet.extracted_values.length)} extracted values · ${rvv.lines.length} return lines</span></div></div></main></div>`;
bind();}
function stat(label,value,foot,ic='file',extra=''){return `<div class="stat ${extra}"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-number">${value}</div><div class="stat-foot">${foot}</div></div>`}
function overview(){return findingHeadline()+ownershipOverview()}
function findingRow(c){return `<li class="finding"><div class="finding-icon">${icon(c.kind==='Judgment required'?'users':'link')}</div><div class="finding-body"><div class="finding-title">${esc(c.title)}</div><div class="finding-meta"><span>${esc(c.key)}</span><span>·</span><span>${esc(c.refs[0])}</span>${c.resolution?tag('Dispositioned','green'):''}</div></div><div class="finding-side"><div class="finding-amount">${c.delta!==null?displayValue(c.delta,c.key):'Review needed'}</div>${tag(c.kind==='Engine diagnostic'?'Engine flag':c.kind==='Judgment required'?'Judgment':'Source mismatch',c.resolution?'green':'amber')}</div><button class="open-arrow" data-finding="${c.id}" aria-label="Review ${esc(c.title)}">${icon('chevron')}</button></li>`}
function summaryPanel(){const old=D.packet.prior_years.return_2024.lines, keys=['F1040.1a','F1040.2b','F1040.7','F1040.11','F1040.24'];return panel('Return at a glance',`<div class="table-wrap"><table class="compact-table"><thead><tr><th>Federal return</th><th class="num">2024 filed</th><th class="num">2025 engine</th><th class="num">Change</th><th>Review</th></tr></thead><tbody>${keys.map(k=>{let l=lineMap()[k],o=old[k],delta=typeof o==='number'?l.value-o:null;return `<tr class="clickable" data-ref="${k}"><td>${esc(l.label)}<small>${k}</small></td><td class="num">${fmt(o)}</td><td class="num">${displayValue(l.value,l.key)}</td><td class="num">${delta===null?' - ':`${delta>0?'+':''}${fmt(delta)}`}</td><td>${tag(D.state.verifications[k]?'Verified':'Unverified',D.state.verifications[k]?'green':'')}</td></tr>`}).join('')}</tbody></table></div><div class="panel-footer"><span>2025 amounts are engine output, pending review.</span><button class="link-btn" data-nav="records">Explore all lines ${icon('arrow')}</button></div>`)}
function reconciliation(){let items=D.checks.filter(c=>(statusFilter==='all'||statusFilter==='open'&&!c.resolution||statusFilter==='resolved'&&c.resolution)&&JSON.stringify(c).toLowerCase().includes(filter.toLowerCase()));return `<div class="stats">${stat('Findings',D.checks.length,'Evidence conflicts and independent checks','link')}${stat('Awaiting disposition',openChecks().length,'Reviewer or partner decision required','alert','alert')}${stat('Dispositioned',D.checks.filter(c=>c.resolution).length,'Reason and evidence recorded','check')}${stat('Working adjustments',Object.keys(D.state.adjustments).length,'Packet-rate effects · independent approval','layers')}</div>${panel('Reconciliation queue',`<div class="toolbar"><input id="filter" value="${esc(filter)}" placeholder="Filter by finding, line, or source…" aria-label="Filter findings"><select id="status-filter" aria-label="Finding status"><option value="all" ${statusFilter==='all'?'selected':''}>All findings</option><option value="open" ${statusFilter==='open'?'selected':''}>Open findings</option><option value="resolved" ${statusFilter==='resolved'?'selected':''}>Dispositioned</option></select></div><ul class="findings">${items.map(findingRow).join('')||'<li class="empty">No findings match these filters.</li>'}</ul><div class="panel-footer"><span>${items.length} findings · Differences are line-level, not aggregate tax effects.</span><button class="link-btn" data-action="refresh">${icon('undo')} Refresh checks</button></div>`)} `}
function documents(){let ds=D.packet.documents.filter(d=>JSON.stringify(d).toLowerCase().includes(filter.toLowerCase()));return `${panel('Source document index',`<div class="toolbar"><input id="filter" value="${esc(filter)}" placeholder="Find a document, issuer, field, or printed amount…" aria-label="Filter documents">${btn(icon('plus')+' Attach evidence','attach','small')}</div><div class="table-wrap"><table class="compact-table"><thead><tr><th>Document</th><th>Extraction</th><th>Return connections</th><th>Disposition</th><th></th></tr></thead><tbody>${ds.map(d=>{let count=documentLines(d.id).length, disposition=D.state.documents[d.id];return `<tr class="clickable" data-ref="${d.id}"><td><strong>${d.id}</strong> · ${esc(d.title)}<small>${esc(d.issuer)} · ${d.page_count} page${d.page_count>1?'s':''} · Received ${date(d.received_at)}</small></td><td>${tag(d.extraction.status.replaceAll('_',' '),d.extraction.status==='extracted'?'green':'amber')}</td><td><span class="source-count">${icon('link')}${count} connected lines</span></td><td>${tag(disposition?.status||'Unaccounted',disposition?'green':'amber')}</td><td>${icon('chevron')}</td></tr>`}).join('')}</tbody></table></div><div class="panel-footer"><span>${ds.length} / 74 documents · A connection does not mean the document is verified.</span></div>`)}${D.state.evidence.length?panel('Attached evidence',`<div class="panel-body">${D.state.evidence.map(e=>`<div class="trace-node"><div><strong>${esc(e.name)}</strong><small>${esc(who(e.actor))} · ${date(e.at)}</small></div>${ref(e.id)}</div>`).join('')}</div>`):''}`}
function documentLines(id){return connectedLines(id)}
function records(){return unifiedWorkpapers()}
function supportingRecords(){const schedule=supportingSchedule();if(schedule!==undefined)return schedule;if(recordTab==='lines')return formExplorer();return lineTable(({retirement:['F8606','F8889','F8938'],deductions:['SchA','F8812','F8863','F2441','F8283','F8867'],state:['SchCA540NR','F540NR','ScheduleS','FTB3885A']})[recordTab]||null)}
function lineTable(forms=null,extra=[]){return reviewLineTable(forms,extra)}
function assetTable(){return panel('Depreciation by asset',`<div class="table-wrap"><table class="compact-table"><thead><tr><th>Asset / method</th><th>Service / life</th><th class="num">Cost</th><th class="num">Federal 2025</th><th class="num">California</th><th class="num">AMT</th><th>Disposition</th></tr></thead><tbody>${rv().assets.map(a=>`<tr class="clickable" data-ref="asset:${a.asset_id}"><td>${esc(a.description)}<small>${esc(a.method)} · ${a.asset_id}</small></td><td>${esc(a.placed_in_service)}<small>${a.life_years} years</small></td><td class="num">${fmt(a.cost)}</td><td class="num">${fmt(a.federal.depreciation_2025)}</td><td class="num">${fmt(a.california.depreciation_2025)}</td><td class="num">${fmt(a.amt.depreciation_2025)}</td><td>${tag(a.disposed?'Disposed':'In service',a.disposed?'amber':'green')}</td></tr>`).join('')}</tbody></table></div><div class="panel-footer">Open any asset for accumulated depreciation, disposition, recapture information and sources.</div>`)}
function books(){return bookTaxBridge()}
function changes(){return planningWorkspace()}
function reviewCore(){const s=D.state;return `<div class="two-col"><div class="stack">${panel('Review notes',`<div class="panel-body">${s.notes.length?s.notes.map(n=>`<div class="record"><h3>${esc(n.text)}</h3><p>${esc(who(n.actor))} · ${date(n.at)} · ${esc(n.target)}</p>${tag(n.resolved?'Resolved':n.blocking?'Blocks filing':'Open',n.resolved?'green':n.blocking?'red':'amber')}${n.resolved?`<p>${esc(n.resolution)}</p>`:btn('Resolve','resolveNote','small',`data-id="${n.id}"`)}</div>`).join(''):'<div class="empty">No review notes yet. Record questions and decisions where the work happens.</div>'}</div>`,btn(icon('plus')+' Add note','note','small'))}${panel('Tasks & client questions',`<div class="panel-body">${s.tasks.length?s.tasks.map(t=>`<div class="trace-node"><div><strong>${esc(t.title)}</strong><small>${esc(who(t.assignee))} · Due ${esc(t.due)} · ${t.status} · ${esc(t.target||'engagement')}</small>${t.answer?`<p>${esc(t.answer)}</p>${t.evidence_ref?ref(t.evidence_ref):''}`:''}</div>${t.status==='open'?btn('Respond','taskUpdate','small',`data-id="${t.id}"`):tag(t.status,'green')}</div>`).join(''):'<div class="empty">Assign a task or prepare a question for a client. Questions stay inside this local workspace.</div>'}</div>`,btn(icon('plus')+' Create task','task','small'))}${panel('Judgments, elections & due diligence',`<div class="panel-body">${s.judgments.length?s.judgments.map(j=>`<div class="record"><h3>${esc(j.subject)}</h3><p>${esc(j.decision)}</p><p>Authority: ${esc(j.authority)}</p>${refs(j.refs)}<p class="footnote">${esc(who(j.actor))} · ${date(j.at)}</p>${j.reviewed_by?tag("Reviewed by "+who(j.reviewed_by),"green"):j.actor!==D.user.id?btn("Review judgment","reviewJudgment","small",`data-id="${j.id}"`):tag("Awaiting another reviewer","amber")}</div>`).join(''):'<div class="empty">Every judgment needs an authority and evidence. Use this record for elections, penalty decisions, due diligence and outside filings.</div>'}</div>`,btn(icon('plus')+' Record judgment','judgment','small'))}</div><div class="stack">${panel('Review signatures',`<div class="panel-body">${['preparer','reviewer','partner'].map(role=>`<div class="progress-item">${role[0].toUpperCase()+role.slice(1)}<span>${s.signatures[role]?esc(who(s.signatures[role].actor)):'Pending'}</span></div>`).join('')}<p class="footnote">You cannot review your own work. Material changes reopen signatures and client approvals.</p>${btn(icon('check')+' Sign as '+D.user.role,'sign','primary small')}</div>`)}${panel('Areas considered',`<div class="panel-body">${D.areas.map(a=>`<div class="progress-item"><i class="status-circle ${s.areas[a]?'done':''}">${s.areas[a]?'✓':''}</i>${canAction('area')?`<button class="link-btn" data-action="area" data-id="${esc(a)}">${esc(a)}</button>`:`<span>${esc(a)}</span>`}</div>`).join('')}</div>`)}</div></div>`}
