function firmData(){return D.administration?D.administration_data:{budget_hours:D.state.budget_hours||D.packet.firm.budget_hours,deadlines:D.packet.firm.deadlines,hours_by_area:Object.fromEntries(Object.keys(D.packet.firm.budget_hours).map(area=>[area,D.state.time.filter(t=>t.area===area).reduce((sum,t)=>sum+t.hours,0)]))}}
