function showFinding(id){if(!canView('reconciliation'))return;let c=D.checks.find(x=>x.id===id);drawer(c.title,`${tag(c.kind,c.resolution?'green':'amber')} ${tag(c.resolution?'Dispositioned':'Open · filing blocker',c.resolution?'green':'red')}<div class="compare-boxes"><div class="compare-box"><small>Engine line amount</small><strong>${displayValue(c.actual,c.key)}</strong></div><div class="compare-box"><small>Evidence / proposed</small><strong>${displayValue(c.expected,c.key)}</strong></div><div class="compare-box difference"><small>Line difference</small><strong>${displayValue(c.delta,c.key)}</strong></div></div><p>${esc(c.detail)}</p><h3>Inspect the evidence</h3>${refs(c.refs)}<h3>Impacted return lines</h3><p class="footnote">${c.affected.length} references reached through the dependency graph.</p>${refs(c.affected.slice(0,6))}${c.affected.length>6?`<details><summary class="link-btn">Show all ${c.affected.length} affected lines</summary>${refs(c.affected.slice(6))}</details>`:''}<h3>Review decision</h3>${c.resolution?`<p>${esc(c.resolution.reason)}</p><p class="footnote">${esc(who(c.resolution.actor))} · ${date(c.resolution.at)}</p>${refs(c.resolution.refs)}${btn('Reopen finding','reopen','small',`data-id="${id}"`)}`:`<div class="actions">${btn(consolidatedLayout?'Disposition &amp; next':'Record disposition',consolidatedLayout?'resolveNext':'resolve','primary',`data-id="${id}"`)}${lineMap()[c.key]&&typeof c.actual==='number'?btn('Propose adjustment','adjust','',`data-key="${c.key}" data-value="${c.expected??c.actual}"`):''}</div><p class="footnote">Disposition records the reviewer’s conclusion. It does not change source documents or recalculate the return.</p>`}<h3>Document judgment or request evidence</h3><div class="actions">${btn('Add review note','note','small',`data-target="${c.key}"`)}${btn('Record judgment','judgment','small',`data-subject="${id}"`)}</div>`,'RECONCILIATION FINDING')}
function objectForRef(r){if(lineMap()[r])return lineMap()[r];if(/^D\d+$/.test(r))return D.packet.documents.find(d=>d.id===r);if(r.startsWith('ev-'))return D.packet.extracted_values.find(e=>e.id===r);if(/^(qa-|msg-|call-)/.test(r))return Object.values(D.packet.client).flat().find(e=>e.id===r);if(r.startsWith('py:/')||r.startsWith('agency:/'))return r.split(':/')[1].split('/').reduce((o,k)=>o?.[k.replaceAll('~1','/').replaceAll('~0','~')],r.startsWith('py:')?D.packet.prior_years:D.packet.tax_agency_records);if(r.startsWith('asset:'))return [...rv().assets,...D.packet.prior_years.asset_records].find(a=>a.asset_id===r.slice(6));if(r.startsWith('household:'))return D.packet.household.people.find(p=>p.id===r.slice(10));if(r.startsWith('timeline:'))return D.packet.timeline.find(t=>t.id===r.slice(9));if(r.startsWith('ref:param.'))return D.packet.engine_reference.parameters[r.slice(10)];if(r.startsWith('ref:fx.SEK.'))return D.packet.fx_rates.SEK_per_USD[r.slice(11)];if(r.startsWith('evidence:'))return D.state.evidence.find(e=>e.id===r);return featureObject(r)}
function showRef(r){if(!canInspect())return;if(scheduleReference(r))return;if(featureReference(r))return;if(r.startsWith('doc:')){let [d,p]=r.slice(4).split('#page');return showDoc(d,Number(p))}if(/^D\d+$/.test(r))return showDoc(r);let o=objectForRef(r);if(o===undefined)return drawer('Reference not available',`<p>${esc(r)} could not be resolved in this version. Inspect the related packet records or switch to the referenced version.</p>`);if(lineMap()[r])return showLine(o);if(r.startsWith('ev-'))return showDoc(o.document_id,o.page,false,null,o.id,currentDrawer?.context?.lineKey);if(r.startsWith('evidence:'))return drawer(o.name,`<p>${esc(who(o.actor))} · ${date(o.at)}</p><p class="footnote">SHA-256 ${esc(o.sha256)}</p>${o.encoding==='base64'?btn('Download attachment','downloadEvidence','primary',`data-id="${o.id}"`):`${evidenceText(o.content)}`}`);drawer(r,`${o.description?`<p>${esc(o.description)}</p>`:''}${scheduleRecord(o)}${o.sources?'<h3>Source connections</h3>'+refs(o.sources):''}<h3>Link this evidence</h3>${btn('Create related-item link','link','small',`data-source="${esc(r)}"`)}`)}
function showLine(l){if(!canInspect())return;focusedLine(l)}
function showDoc(id,pg=1,paging=false,focusTarget=null,evidenceId=null,lineKey=null){
  if(!canView('documents'))return;
  const d=D.packet.documents.find(d=>d.id===id);if(!d?.pages.length)return;
  const p=d.pages.find(p=>p.page===pg)||d.pages[0],index=d.pages.indexOf(p),evs=D.packet.extracted_values.filter(e=>e.document_id===id&&e.page===p.page),dest=documentLines(id);
  const pageRefs=new Set([`doc:${id}#page${p.page}`,...evs.map(e=>e.id)]),pageDest=connectedLines(`doc:${id}#page${p.page}`);
  const previous=Number($('#doc-page')?.dataset.current||p.page),direction=paging?(p.page>previous?'forward':'backward'):'';
  const contextLineKey=lineKey||currentDrawer?.context?.lineKey;
  const contextLine=contextLineKey?lineMap()[contextLineKey]:null;
  const selectedEvidence=evidenceId||(paging?currentDrawer?.context?.evidenceId:null);
  const extracted=selectedEvidence?D.packet.extracted_values.find(e=>e.id===selectedEvidence&&e.document_id===id&&e.page===p.page):null;
  const match=matchedSource(p.printed_content,extracted);
  const context={lineKey:contextLineKey,form:contextLine?.form,evidenceId:selectedEvidence,label:`${id}, page ${p.page}`,wide:!!contextLine};
  const content=`${tag(id)} ${tag(d.document_type)}<p class="footnote">${esc(d.file_name)} &middot; ${d.page_count} pages &middot; ${esc(d.belongs_to)}</p>
    <div class="document-pager" role="group" tabindex="-1" aria-label="Document page navigation">
      ${btn('&larr; Previous','docPrevious','small',`${index===0?'disabled':''} aria-label="Previous document page"`)}
      <div class="document-page-counter"><label for="doc-page">Page</label><input id="doc-page" type="text" inputmode="numeric" pattern="[0-9]+" value="${p.page}" data-id="${id}" data-current="${p.page}" aria-label="Page number" aria-describedby="doc-page-hint doc-page-error" autocomplete="off"><span>/ ${d.page_count}</span></div>
      ${btn('Next &rarr;','docNext','small',`${index===d.pages.length-1?'disabled':''} aria-label="Next document page"`)}
      <span class="sr-only" role="status" aria-live="polite">Page ${p.page} of ${d.page_count}</span>
      <div class="document-page-help"><span id="doc-page-hint">Type a page and press Enter, or use left / right arrow keys.</span><span>${evs.length} extracted values</span></div>
      <div id="doc-page-error" class="document-page-error" role="alert" hidden></div>
    </div>
    ${evidenceFocusHtml(extracted,match)}${reverseEvidencePanel(`doc:${id}#page${p.page}`)}
    <div class="document-sheet ${direction?'page-slide-'+direction:''}">
      <div class="page-text"><div class="document-page-label">${id} / PAGE ${p.page} &middot; SOURCE TEXT REPRESENTATION</div>${match.html}</div>
      <p class="footnote">Verbatim printed_content from the packet. No original image or fabricated highlight is shown.</p><details class="trace-details"><summary>Extracted fields on page ${p.page} &middot; ${evs.length}</summary>
      ${evs.map(e=>`<button class="trace-node" data-ref="${e.id}"><span><strong>${esc(e.label)}</strong><small>${e.id} &middot; ${Math.round(e.confidence*100)}% confidence</small></span><span>${fmt(e.value)} ${icon('chevron')}</span></button>`).join('')||'<div class="callout">This page has no extracted values. Review the printed text for omitted evidence.</div>'}
      </details><details class="trace-details"><summary>Return connections from page ${p.page} &middot; ${pageDest.length}</summary>${refs(pageDest.map(l=>l.key))||'<p>No direct return connections from this page.</p>'}</details>
    </div>
    <details class="trace-details"><summary>Document connections (all pages) &middot; ${dest.length}</summary>${refs(dest.map(l=>l.key))||'<p>No direct return use found. Record why this document is not used.</p>'}</details>
    <details class="trace-details"><summary>Document disposition</summary>${D.state.documents[id]?raw(D.state.documents[id]):'<p>This document has not been accounted for by a preparer.</p>'}${btn('Record disposition','document','primary',`data-id="${id}"`)}</details>`;
  const body=contextLine?`<div class="trace-workspace">${numberContext(contextLine)}<div class="trace-main">${lineWarnings(contextLine)}${content}</div></div>`:content;
  if(paging&&currentDrawer&&$('.drawer-content')){
    // Turning a page stays within the same document, not a new drawer history entry.
    currentDrawer.body=body;currentDrawer.context=context;$('.drawer-content').innerHTML=body;if($('.trace-breadcrumbs'))$('.trace-breadcrumbs').outerHTML=traceCrumbs(context);$('.drawer-content').scrollTop=0;
    const target=focusTarget==='input'?$('#doc-page'):$(`[data-action="${focusTarget}"]`);
    (target&&!target.disabled?target:$('.document-pager')).focus({preventScroll:true});
    if(focusTarget==='input')$('#doc-page').select();
  }else drawer(d.title,body,'SOURCE DOCUMENT',context);
  if(extracted&&$('#evidence-highlight'))$('#evidence-highlight').scrollIntoView({block:'center',behavior:'instant'});
}
function turnDocumentPage(direction){
  const input=$('#doc-page');if(!input||!canView('documents'))return;
  const d=D.packet.documents.find(d=>d.id===input.dataset.id),index=d?.pages.findIndex(p=>p.page===Number(input.dataset.current)),next=d?.pages[index+direction];
  if(next)showDoc(d.id,next.page,true,direction>0?'docNext':'docPrevious');
}
function jumpDocumentPage(){
  const input=$('#doc-page');if(!input||!canView('documents'))return;
  const d=D.packet.documents.find(d=>d.id===input.dataset.id),value=input.value.trim(),requested=Number(value);
  if(!/^[0-9]+$/.test(value)||!Number.isSafeInteger(requested)||requested<1||requested>d.page_count||!d.pages.some(p=>p.page===requested)){
    const message=$('#doc-page-error');message.textContent=`Enter an available page number between 1 and ${d.page_count}.`;message.hidden=false;input.setAttribute('aria-invalid','true');return;
  }
  if(requested===Number(input.dataset.current)){input.value=String(requested);input.removeAttribute('aria-invalid');$('#doc-page-error').hidden=true;return;}
  showDoc(d.id,requested,true,'input');
}

function field(name,label,type='text',value='',options=[]){if(type==='select')return `<label>${label}<select name="${name}" required>${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o.replaceAll('_',' ')];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;if(type==='textarea')return `<label>${label}<textarea name="${name}" required>${esc(value)}</textarea></label>`;return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''} required></label>`}
